def valid_date(date):
    # Check if the date string is not empty
    if not date:
        return False

    # Check if the date string is in the correct format mm-dd-yyyy
    try:
        month, day, year = map(int, date.split('-'))
    except ValueError:
        return False

    # Check the number of days in each month
    if month < 1 or month > 12:
        return False
    if day < 1 or day > 31:
        return False
    if month == 2:
        if year % 4 == 0:
            if day > 29:
                return False
        else:
            if day > 28:
                return False
    elif month in [4, 6, 9, 11]:
        if day > 30:
            return False

    # If all checks pass, the date is valid
    return True
```

